UPDATE fin.transacoes t SET categoria_id = r.categoria_id, categoria_fonte = 'regra', categorizada_em = now()
FROM (SELECT DISTINCT ON (t2.id) t2.id, r2.categoria_id FROM fin.transacoes t2 JOIN fin.regras_categoria r2 ON t2.descricao ILIKE '%' || r2.padrao || '%' WHERE t2.categoria_id IS NULL ORDER BY t2.id, (t2.descricao ILIKE 'IOF de%' AND r2.padrao = 'IOF de') DESC, length(r2.padrao) DESC) r
WHERE t.id = r.id;

