const pend = $input.all().map(i => i.json).filter(r => r.id);
if (!pend.length) return [];
const cats = $('Categorias').all().map(i => i.json.nome);
const schema = { type: 'object', properties: { resultados: { type: 'array', items: { type: 'object',
  properties: { id: { type: 'integer' }, categoria: { type: 'string', enum: cats } }, required: ['id', 'categoria'] } } },
  required: ['resultados'] };
const sys = "Você classifica compras de cartão de crédito brasileiro em UMA categoria da lista. Use 'Outros' só se nada servir. Responda apenas JSON.\nCategorias: " + cats.join(', ');
const out = [];
for (let i = 0; i < pend.length; i += 6) {
  const b = pend.slice(i, i + 6);
  out.push({ json: { body: { model: $env.LLM_MODEL || 'categorizador', temperature: 0, max_tokens: 400,
    messages: [{ role: 'system', content: sys }, { role: 'user', content: b.map(r => `${r.id}|${r.descricao}|${r.valor}`).join('\n') }],
    response_format: { type: 'json_schema', json_schema: { name: 'r', strict: true, schema } } } } });
}
return out;

const validos = new Set($('Buscar pendentes').all().map(i => i.json.id).filter(Boolean).map(Number));
const cats = new Set($('Categorias').all().map(i => i.json.nome));
const res = [];
for (const it of $input.all()) {
  try {
    const r = JSON.parse(it.json.choices[0].message.content).resultados;
    for (const x of r) if (validos.has(Number(x.id)) && cats.has(x.categoria)) res.push({ id: Number(x.id), categoria: x.categoria });
  } catch (e) { /* Lotes inválidos permanecem sem categoria para a próxima execução. */ }
}
return [{ json: { payload: JSON.stringify(res), total: res.length } }];
